/*
 * Darwin-VM-compatible Apple implementation system registers.
 * SPDX-License-Identifier: AGPL-3.0-or-later
 *
 * The register list, encodings and reset values are generated by
 * scripts/darwin-port/gen-modern-sysregs.py from qemu-sptm 2867d847
 * (scripts/darwin/{sysregs,dumpregs}.py and hw/arm/apple_regs.c). These are
 * read-as-written compatibility stores with no hardware effects: CTRR/CTXR
 * protection, AMX, HID chicken bits, APCTL key diversification and the other
 * implementation registers do not do what the real silicon does. They exist
 * so unchanged firmware can proceed past register programming. Registers with
 * modeled behavior (GXF, guarded banks, timers, SPRR, APSTS) belong to their
 * own modules and are excluded from this table.
 */
#include "qemu/osdep.h"
#include "qapi/error.h"
#include "cpu.h"
#include "internals.h"
#include "cpu-features.h"
#include "system/tcg.h"
#include "modern-sysregs.h"

#include "modern-sysregs.inc.c"

QEMU_BUILD_BUG_ON(APPLE_MODERN_OPAQUE_COUNT > APPLE_MODERN_OPAQUE_MAX);

bool arm_apple_modern_sysregs_validate(ARMCPU *cpu, Error **errp)
{
    if (!cpu->apple_modern_sysregs) {
        return true;
    }
    if (!cpu->apple_modern_gxf) {
        error_setg(errp, "apple-modern-sysregs requires apple-modern-gxf");
        return false;
    }
    return arm_apple_modern_gxf_validate(cpu, errp);
}

/*
 * Darwin's PMC0/PMC1 return an increasing count (zero before the first
 * instruction) and ignore writes. Increments are deterministic here instead
 * of random; they do not count instructions or events.
 */
static uint64_t apple_modern_pmc_read(CPUARMState *env, const ARMCPRegInfo *ri)
{
    int index = ri->crm == 1;

    if (env->pc == 0) {
        return 0;
    }
    env->modern_sysregs.pmc[index] += index ? 100 : 1000;
    return env->modern_sysregs.pmc[index];
}

static void apple_modern_pmc_write(CPUARMState *env, const ARMCPRegInfo *ri,
                                   uint64_t value)
{
}

static void apple_modern_pmc_reset(CPUARMState *env, const ARMCPRegInfo *ri)
{
    env->modern_sysregs.pmc[ri->crm == 1] = 0;
}

static const ARMCPRegInfo apple_modern_pmc_regs[] = {
    { .name = "PMC0", .state = ARM_CP_STATE_AA64, .access = PL1_RW,
      .opc0 = 3, .opc1 = 2, .crn = 15, .crm = 0, .opc2 = 0,
      .type = ARM_CP_NO_RAW | ARM_CP_IO,
      .readfn = apple_modern_pmc_read, .writefn = apple_modern_pmc_write,
      .resetfn = apple_modern_pmc_reset },
    { .name = "PMC1", .state = ARM_CP_STATE_AA64, .access = PL1_RW,
      .opc0 = 3, .opc1 = 2, .crn = 15, .crm = 1, .opc2 = 0,
      .type = ARM_CP_NO_RAW | ARM_CP_IO,
      .readfn = apple_modern_pmc_read, .writefn = apple_modern_pmc_write,
      .resetfn = apple_modern_pmc_reset },
};

void arm_register_apple_modern_sysregs(ARMCPU *cpu)
{
    assert(cpu->apple_modern_sysregs);
    define_arm_cp_regs(cpu, apple_modern_sysregs);
    define_arm_cp_regs(cpu, apple_modern_pmc_regs);
}

void arm_register_apple_modern_sysreg_aliases(ARMCPU *cpu)
{
    assert(cpu->apple_modern_sysregs);
    for (size_t i = 0; i < ARRAY_SIZE(apple_modern_sysreg_aliases); i++) {
        arm_define_vhe_alias(cpu, apple_modern_sysreg_aliases[i].src,
                             apple_modern_sysreg_aliases[i].dst,
                             apple_modern_sysreg_aliases[i].alias,
                             apple_modern_sysreg_aliases[i].src_name,
                             apple_modern_sysreg_aliases[i].dst_name,
                             apple_modern_sysreg_aliases[i].alias_name);
    }
}

bool arm_apple_modern_sysreg_set(ARMCPU *cpu, const char *name, uint64_t value)
{
    if (!cpu->apple_modern_sysregs) {
        return false;
    }
    for (size_t i = 0; i < APPLE_MODERN_OPAQUE_COUNT; i++) {
        if (!strcmp(apple_modern_sysreg_names[i], name)) {
            cpu->env.modern_sysregs.opaque[i] = value;
            return true;
        }
    }
    return false;
}
